+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Arrays;
+import java.util.EnumSet;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.function.Predicate;
+import java.util.regex.Pattern;
+
+/**
+ * A filter understood by {@link CustomerRepository}.
+ *
+ * <p>The name text is split on whitespace into terms; every term must appear,
+ * ignoring case and accents, in the first name or the last name. With no
+ * statuses, every status matches; otherwise the status must be one of them.
+ *
+ * @param name     free text matched against first and last name; never {@code null}
+ * @param statuses statuses to show; empty means every status; never {@code null}
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    /** Matches every customer. */
+    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());
+
+    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
+    private static final Pattern MARKS = Pattern.compile("\\p{M}+");
+
+    public CustomerFilter {
+        name = (name == null) ? "" : name.strip();
+        statuses = (statuses == null || statuses.isEmpty())
+                ? Set.of()
+                : Set.copyOf(EnumSet.copyOf(statuses));
+    }
+
+    public boolean isEmpty() {
+        return name.isEmpty() && statuses.isEmpty();
+    }
+
+    /** Returns this filter as a predicate over customers. */
+    public Predicate<Customer> toPredicate() {
+        List<String> terms = Arrays.stream(WHITESPACE.split(name))
+                .filter(term -> !term.isEmpty())
+                .map(CustomerFilter::fold)
+                .toList();
+        Set<CustomerStatus> wanted = statuses;
+        return customer -> {
+            if (!wanted.isEmpty() && !wanted.contains(customer.status())) {
+                return false;
+            }
+            if (terms.isEmpty()) {
+                return true;
+            }
+            String first = fold(customer.firstName());
+            String last = fold(customer.lastName());
+            return terms.stream().allMatch(term -> first.contains(term) || last.contains(term));
+        };
+    }
+
+    /** Lower-cases and strips accents, so {@code Mäkinen} folds to {@code makinen}. */
+    static String fold(String text) {
+        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFD);
+        return MARKS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
+    }
+}
