+    private void onFilterChanged() {
+        if (applyingUrl) {
+            return;
+        }
+        applyFilter(new CustomerFilter(nameFilter.getValue(), statusFilter.getValue()));
+        writeUrl();
+    }
+
+    private void applyFilter(CustomerFilter newFilter) {
+        if (newFilter.equals(filter)) {
+            return;
+        }
+        filter = newFilter;
+        int count = customerService.count(filter);
+        prefetchedCount = count;
+        updateSummary(count);
+        grid.getDataProvider().refreshAll();
+    }
+
+    private void updateSummary(int matching) {
+        summary.setText("Showing " + matching + " of " + totalCount);
+    }
+
+    private void writeUrl() {
+        Map<String, List<String>> parameters = new LinkedHashMap<>();
+        if (!filter.name().isEmpty()) {
+            parameters.put(NAME_PARAMETER, List.of(filter.name()));
+        }
+        if (!filter.statuses().isEmpty()) {
+            parameters.put(STATUS_PARAMETER, List.of(EnumSet.copyOf(filter.statuses()).stream()
+                    .map(CustomerStatus::name)
+                    .collect(Collectors.joining(","))));
+        }
+        getUI().ifPresent(ui -> ui.getPage().getHistory()
+                .replaceState(null, new Location("", new ReadableQueryParameters(parameters))));
+    }
+
+    /** Query parameters that keep the commas of the status list readable, as in {@code status=ACTIVE,CLOSED}. */
+    private static final class ReadableQueryParameters extends QueryParameters {
+
+        ReadableQueryParameters(Map<String, List<String>> parameters) {
+            super(parameters);
+        }
+
+        @Override
+        public String getQueryString() {
+            return getParameters().entrySet().stream()
+                    .flatMap(entry -> entry.getValue().stream()
+                            .map(value -> encode(entry.getKey()) + "=" + encode(value)))
+                    .collect(Collectors.joining("&"));
+        }
+
+        private static String encode(String text) {
+            return URLEncoder.encode(text, StandardCharsets.UTF_8)
+                    .replace("+", "%20")
+                    .replace("%2C", ",");
+        }
+    }
+
+    static Set<CustomerStatus> parseStatuses(List<String> values) {
+        Set<CustomerStatus> statuses = EnumSet.noneOf(CustomerStatus.class);
+        values.stream()
+                .flatMap(value -> Arrays.stream(value.split(",")))
+                .map(String::strip)
+                .forEach(token -> Arrays.stream(CustomerStatus.values())
+                        .filter(status -> status.name().equalsIgnoreCase(token))
+                        .forEach(statuses::add));
+        return statuses;
     }

