+    }
+
+    @AfterAll
+    static void stopBrowser() {
+        if (browser != null) {
+            browser.close();
+        }
+        if (playwright != null) {
+            playwright.close();
+        }
+    }
+
+    private Locator summary(Page page) {
+        return page.locator("#customer-summary");
+    }
+
+    @Test
+    void typingIsDebouncedAndUrlFollows() {
