+        page.navigate("http://localhost:" + port + "/");
+        page.waitForFunction("() => document.querySelector('#customer-summary')?.textContent === 'Showing 500 of 500'");
+        page.waitForTimeout(1000);
+        Object historyBefore = page.evaluate("history.length");
+        queryLog.clear();
+
+        Locator input = page.locator("vaadin-text-field input");
+        input.pressSequentially("virtanen", new Locator.PressSequentiallyOptions().setDelay(80));
+        page.waitForTimeout(1500);
+        assertTrue(page.url().endsWith("/?name=virtanen"), page.url());
+        assertTrue(queryLog.pageQueries().size() <= 2);
+
+        page.locator("vaadin-multi-select-combo-box input").click();
+        page.locator("vaadin-multi-select-combo-box-item", new Page.LocatorOptions().setHasText("CLOSED")).click();
+        page.locator("vaadin-multi-select-combo-box-item", new Page.LocatorOptions().setHasText("ACTIVE")).click();
+        page.keyboard().press("Escape");
+        page.waitForTimeout(1000);
+        assertTrue(page.url().endsWith("/?name=virtanen&status=ACTIVE,CLOSED"), page.url());
+
+        input.fill("");
+        page.waitForTimeout(1000);
+        assertTrue(page.url().endsWith("/?status=ACTIVE,CLOSED"), page.url());
+        page.locator("vaadin-multi-select-combo-box input").click();
+        page.locator("vaadin-multi-select-combo-box-item", new Page.LocatorOptions().setHasText("CLOSED")).click();
+        page.locator("vaadin-multi-select-combo-box-item", new Page.LocatorOptions().setHasText("ACTIVE")).click();
